var rig=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>("Assets/Resources/PlayerRig.prefab");
var players=rig.GetComponentsInChildren<TopDownPlayer>(true).Select(p=>{var s=new UnityEditor.SerializedObject(p);return new {model=UnityEditor.AssetDatabase.GetAssetPath(s.FindProperty("character3DPrefab").objectReferenceValue),controller=UnityEditor.AssetDatabase.GetAssetPath(s.FindProperty("character3DController").objectReferenceValue),shader=UnityEditor.AssetDatabase.GetAssetPath(s.FindProperty("character3DShader").objectReferenceValue),scale=s.FindProperty("character3DScale").floatValue};}).ToArray();
const string f="Assets/ChibiSurvivor/Player/SimpleHeroStudy/SimpleHero_Stage5_Slash.fbx";
var model=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(f);
return new {players,playing=UnityEditor.EditorApplication.isPlaying,scenes=Enumerable.Range(0,UnityEngine.SceneManagement.SceneManager.sceneCount).Select(i=>{var s=UnityEngine.SceneManagement.SceneManager.GetSceneAt(i);return new{s.path,s.isDirty};}).ToArray(),model=model==null?null:new{root=model.name,bones=model.GetComponentsInChildren<Transform>().Select(t=>t.name).Take(30).ToArray(),materials=model.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Where(m=>m!=null).Distinct().Select(m=>new{m.name,shader=m.shader.name}).ToArray()},clips=UnityEditor.AssetDatabase.LoadAllAssetsAtPath(f).OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__preview__")).Select(c=>new{c.name,c.length}).ToArray()};
